const route = /^\/psy/.test(r.data) ? 'p:h' : p[0] + ':' + (p[1] || '');
switch (route) {
  case 'p:h':
    return done('ok', '<b>Кабінет психолога</b>\n' + esc(me.name),
      column([btn('📋 Записи на консультації', 'p:bk'), btn('👥 Мої сеанси БСТ', 'p:bst'), btn('📅 Події', 'p:ev'), HOME]));
  case 'p:bk': {
    // Записи всіх психологів на PSY_PEER_VIEW_DAYS днів; ім'я й телефон людини — лише у своїх (§4.8, §8).
    const days = num('PSY_PEER_VIEW_DAYS', 14);
    const list = all('Записи').filter((b) => b.status === 'active' && Date.parse(b.starts_at) > now && Date.parse(b.starts_at) <= now + days * 86400000).sort(byTime);
    const lines = ['<b>Записи на ' + days + ' днів</b>'];
    if (!list.length) lines.push('', 'Записів немає.');
    let current = null;
