      if (b.psychologist_id === me._key) {
        lines.push('• ' + time(b.starts_at) + ' — <b>ваш запис</b>: ' + esc(b.client_name || 'без імені') + (b.client_phone ? ', +' + esc(b.client_phone) : ''));
