// Екран → виклики Telegram: кнопка редагує своє повідомлення, решта (і new_message) — нове повідомлення.
const u = $node['Розбір'].json;
const s = $json.screen || {};
const clean = (o) => { const x = {}; for (const k of Object.keys(o)) if (o[k] !== null && o[k] !== undefined) x[k] = o[k]; return x; };
const edit = !!u.callback_id && !!u.message_id && !s.new_message;
const message = { chat_id: Number(u.chat_id), text: s.text, parse_mode: s.parse_mode || 'HTML', reply_markup: s.reply_markup };
return [{
  ok: $json.ok,
  code: $json.code,
  edit: edit ? clean(Object.assign({ message_id: u.message_id }, message)) : null,
  send: edit ? null : clean(message),
  notifications: ($json.notifications || []).map((n) => clean({ chat_id: Number(n.chat_id), text: n.text, parse_mode: n.parse_mode || 'HTML', reply_markup: n.reply_markup })),
  commands: $json.commands || null,
  file: $json.file || null,
}];

const list = $json.notifications || [];
const batches = [];
for (let i = 0; i < list.length; i += 100) batches.push({ messages: list.slice(i, i + 100) });
return batches;

const all = (name) => { try { return $node[name].all || []; } catch (e) { return []; } };
const cfg = {};
for (const s of all('Налаштування')) cfg[s.key] = s.value;
const num = (key, fallback) => { const v = parseFloat(cfg[key]); return isNaN(v) ? fallback : v; };
const setting = (key, fallback) => (cfg[key] && String(cfg[key]).trim()) || fallback;
const TZ = setting('timezone', 'Europe/Kyiv');
const now = Date.now();
const nowIso = new Date(now).toISOString();
// Місцевий час — у поясі settings.timezone (не в поясі сценарію): дата, година, день тижня.
const local = (ms) => {
  const o = {};
  for (const p of new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23', weekday: 'short' }).formatToParts(new Date(ms))) o[p.type] = p.value;
  return { date: o.year + '-' + o.month + '-' + o.day, hour: Number(o.hour) % 24, minute: o.minute, weekday: o.weekday, day: o.day, month: o.month };
};
const DAYS = { Sun: 'нд', Mon: 'пн', Tue: 'вт', Wed: 'ср', Thu: 'чт', Fri: 'пт', Sat: 'сб' };
const pad = (n) => (n < 10 ? '0' : '') + n;
const hm = (iso) => { const l = local(Date.parse(iso)); return pad(l.hour) + ':' + l.minute; };
const when = (iso) => { const l = local(Date.parse(iso)); return DAYS[l.weekday] + ' ' + l.day + '.' + l.month + ', ' + pad(l.hour) + ':' + l.minute; };
const today = local(now);
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const FORMATS = { online: 'онлайн', offline: 'офлайн' };
const fmt = (f) => FORMATS[f] || f || '';
const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
const enc = (key) => {
  const k = String(key);
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(k)) return k;
  let bits = '';
  for (const ch of k.replace(/-/g, '')) bits += parseInt(ch, 16).toString(2).padStart(4, '0');
  bits += '0000';
  let out = '';
  for (let i = 0; i < bits.length; i += 6) out += B64[parseInt(bits.slice(i, i + 6), 2)];
  return out;
};
const btn = (text, data) => ({ text: text, callback_data: data });
const message = (chatId, text, buttons) => ({ chat_id: Number(chatId), text: text, parse_mode: 'HTML',
  reply_markup: buttons && buttons.length ? { inline_keyboard: buttons } : null });
// Уже надіслане за останню добу з хвостиком — щоб не пробувати вставити ті самі рядки reminders щоп'ять хвилин.
const done = {};
for (const r of all('Уже надіслано')) done[r.kind + '|' + r.target_id + '|' + Number(r.offset_min || 0)] = true;
const out = [];
const claim = (kind, target, offset, messages, extra) => {
  if (done[kind + '|' + target + '|' + offset]) return;
