const OFFSETS = String(setting('REMINDER_MINUTES', '1440,60,10')).split(',').map((s) => parseInt(s, 10))
  .filter((n) => n > 0).sort((a, b) => a - b);
const remind = (kind, target, startsIso, createdIso, chatId, text, buttons) => {
