  const cutoff = new Date(now);
  cutoff.setMonth(cutoff.getMonth() - months);
  claim('retention', today.date, 0, [], { run: 'retention', cutoff: cutoff.toISOString() });
}
return out;

// Рядок reminders, який уже був (unique), — відмова: це повідомлення пішло раніше, тож його відкидаємо.
