}
const clean = (m) => { const o = {}; for (const k of Object.keys(m)) if (m[k] != null) o[k] = m[k]; return o; };
const out = [];
for (let i = 0; i < messages.length; i += 100) out.push({ messages: messages.slice(i, i + 100).map(clean) });
